      --card-shadow-hover: 0 8px 32px rgba(45, 106, 79, 0.15);
      --radius: 16px;
      --radius-sm: 12px;
      --radius-xs: 8px;
      --transition: 250ms cubic-bezier(0.4, 0, 0.2, 1);
      --max-width: 1200px;
    }

    html { scroll-behavior: smooth; }

    body {
      font-family: 'Nunito', sans-serif;
