      backdrop-filter: blur(12px);
      border-bottom: 1px solid rgba(45, 106, 79, 0.08);
    }
    .header__inner {
      display: flex; align-items: center; justify-content: space-between;
      max-width: var(--max-width); margin: 0 auto; padding: 16px 24px;
    }
    .header__logo {
      display: flex; align-items: center; gap: 10px;
      font-family: 'Poppins', sans-serif; font-weight: 800; font-size: 1.5rem;
      color: var(--green-700);
    }
    .header__logo-icon {
      width: 36px; height: 36px; background: var(--green-700); border-radius: 50%;
      display: flex; align-items: center; justify-content: center;
    }
    .header__logo-icon svg { width: 20px; height: 20px; }
    .header__nav { display: flex; gap: 32px; align-items: center; }
    .header__nav a {
      font-weight: 600; font-size: 0.95rem; color: var(--text-mid);
      transition: color var(--transition); position: relative; padding: 4px 0;
    }
    .header__nav a:hover, .header__nav a:focus-visible { color: var(--green-700); }
    .header__nav a::after {
      content: ''; position: absolute; bottom: -2px; left: 0; width: 0; height: 2px;
      background: var(--green-500); border-radius: 1px; transition: width var(--transition);
    }
    .header__nav a:hover::after { width: 100%; }
    .header__cta {
      background: var(--green-700); color: var(--white); padding: 10px 24px;
      border-radius: 50px; font-weight: 700; font-size: 0.9rem;
      transition: background var(--transition), transform var(--transition);
    }
    .header__cta:hover { background: var(--green-600); transform: translateY(-1px); }
    .header__cta:focus-visible { outline: 3px solid var(--green-500); outline-offset: 2px; }
    .header__mobile-toggle {
      display: none; background: none; padding: 8px;
      color: var(--green-700);
    }

    /* ===== HERO ===== */
    .hero {
      padding: 80px 0 60px;
      background: linear-gradient(135deg, var(--cream) 0%, var(--green-50) 50%, var(--cream) 100%);
      position: relative; overflow: hidden;
    }
    .hero__inner {
      max-width: var(--max-width); margin: 0 auto; padding: 0 24px;
      display: grid; grid-template-columns: 1fr 1fr; gap: 60px; align-items: center;
    }
    .hero__content { position: relative; z-index: 2; }
    .hero__badge {
      display: inline-flex; align-items: center; gap: 8px;
      background: var(--green-100); color: var(--green-700);
      padding: 8px 16px; border-radius: 50px; font-size: 0.85rem; font-weight: 700;
      margin-bottom: 24px;
    }
    .hero__badge svg { width: 16px; height: 16px; }
    .hero h1 {
      font-size: clamp(2.5rem, 5vw, 3.5rem); font-weight: 800;
      color: var(--green-900); margin-bottom: 20px;
    }
    .hero h1 span { color: var(--orange); }
    .hero__subtitle {
      font-size: 1.15rem; color: var(--text-mid); max-width: 500px;
      margin-bottom: 36px; line-height: 1.7;
    }
    .hero__actions { display: flex; gap: 16px; flex-wrap: wrap; }
    .btn-primary {
      background: var(--green-700); color: var(--white); padding: 16px 32px;
      border-radius: 50px; font-weight: 700; font-size: 1rem;
      transition: all var(--transition); display: inline-flex; align-items: center; gap: 8px;
    }
    .btn-primary:hover { background: var(--green-600); transform: translateY(-2px); box-shadow: 0 8px 24px rgba(45,106,79,0.25); }
    .btn-primary:focus-visible { outline: 3px solid var(--green-500); outline-offset: 2px; }
    .btn-secondary {
      background: var(--white); color: var(--green-700); padding: 16px 32px;
      border-radius: 50px; font-weight: 700; font-size: 1rem;
      border: 2px solid var(--green-700); transition: all var(--transition);
      display: inline-flex; align-items: center; gap: 8px;
    }
    .btn-secondary:hover { background: var(--green-50); transform: translateY(-2px); }
    .btn-secondary:focus-visible { outline: 3px solid var(--green-500); outline-offset: 2px; }
    .btn-primary svg, .btn-secondary svg { width: 18px; height: 18px; }
    .hero__visual {
      position: relative; display: flex; align-items: center; justify-content: center;
    }
    .hero__image-wrapper {
      width: 100%; aspect-ratio: 1; border-radius: 32px; overflow: hidden;
      background: linear-gradient(135deg, var(--green-100), var(--cream-dark));
      display: flex; align-items: center; justify-content: center;
      position: relative;
    }
    .hero__image-wrapper svg { width: 60%; height: 60%; opacity: 0.6; color: var(--green-600); }
    .hero__float-card {
      position: absolute; background: var(--white); border-radius: var(--radius);
      padding: 16px 20px; box-shadow: var(--card-shadow); display: flex;
      align-items: center; gap: 12px; font-weight: 700; font-size: 0.9rem;
    }
    .hero__float-card--top { top: -10px; right: -10px; }
    .hero__float-card--bottom { bottom: 20px; left: -20px; }
    .hero__float-icon {
      width: 40px; height: 40px; border-radius: 12px;
      display: flex; align-items: center; justify-content: center;
    }
    .hero__float-icon--green { background: var(--green-100); color: var(--green-700); }
    .hero__float-icon--orange { background: #FEF0E0; color: var(--orange); }
    .hero__float-icon svg { width: 20px; height: 20px; }

    /* ===== FEATURED PRODUCTS ===== */
