      font-size: clamp(1.8rem, 3.5vw, 2.5rem); font-weight: 800;
      color: var(--green-900); text-align: center; margin-bottom: 8px;
    }
    .section-subtitle {
      font-size: 1.05rem; color: var(--text-mid); text-align: center;
      max-width: 560px; margin: 0 auto 48px; line-height: 1.7;
    }

    .featured {
      padding: 80px 0; background: var(--white);
    }
    .carousel { position: relative; }
    .carousel__track-wrapper {
      overflow: hidden; border-radius: var(--radius);
    }
    .carousel__track {
      display: flex; gap: 24px; transition: transform 500ms cubic-bezier(0.4, 0, 0.2, 1);
      padding: 8px 4px;
    }
    .product-card {
      min-width: 260px; flex: 0 0 260px; background: var(--cream);
      border-radius: var(--radius); overflow: hidden;
      box-shadow: var(--card-shadow); transition: all var(--transition);
    }
    .product-card:hover { transform: translateY(-6px); box-shadow: var(--card-shadow-hover); }
    .product-card__image {
      height: 180px; background: linear-gradient(135deg, var(--green-50), var(--cream-dark));
      display: flex; align-items: center; justify-content: center; position: relative;
    }
    .product-card__image svg { width: 48px; height: 48px; color: var(--green-500); opacity: 0.5; }
    .product-card__body { padding: 20px; }
    .product-card__name {
      font-family: 'Poppins', sans-serif; font-weight: 700; font-size: 1rem;
      margin-bottom: 6px; color: var(--green-900);
    }
    .product-card__desc {
      font-size: 0.85rem; color: var(--text-light); margin-bottom: 12px;
      line-height: 1.5; display: -webkit-box; -webkit-line-clamp: 2;
      -webkit-box-orient: vertical; overflow: hidden;
    }
    .product-card__price {
      font-family: 'Poppins', sans-serif; font-weight: 800; font-size: 1.2rem;
      color: var(--green-700);
    }
    .carousel__btn {
      position: absolute; top: 50%; transform: translateY(-50%);
      width: 48px; height: 48px; border-radius: 50%; background: var(--white);
      box-shadow: 0 4px 16px rgba(0,0,0,0.12); display: flex;
      align-items: center; justify-content: center; z-index: 10;
      transition: all var(--transition); color: var(--green-700);
    }
    .carousel__btn:hover { background: var(--green-700); color: var(--white); }
    .carousel__btn:focus-visible { outline: 3px solid var(--green-500); outline-offset: 2px; }
    .carousel__btn--prev { left: -24px; }
    .carousel__btn--next { right: -24px; }
    .carousel__btn svg { width: 24px; height: 24px; }
    .carousel__btn:disabled { opacity: 0.3; cursor: default; }
    .carousel__btn:disabled:hover { background: var(--white); color: var(--green-700); }

    /* ===== SEASONAL PICKS ===== */
    .seasonal { padding: 80px 0; background: var(--cream); }
    .seasonal__grid {
      display: grid; grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
      gap: 24px;
    }
    .seasonal-card {
      background: var(--white); border-radius: var(--radius); overflow: hidden;
      box-shadow: var(--card-shadow); transition: all var(--transition);
    }
    .seasonal-card:hover { transform: translateY(-4px); box-shadow: var(--card-shadow-hover); }
    .seasonal-card__image {
      height: 160px; display: flex; align-items: center; justify-content: center;
    }
    .seasonal-card__image svg { width: 40px; height: 40px; opacity: 0.5; }
    .seasonal-card__body { padding: 20px; }
    .seasonal-card__name {
      font-family: 'Poppins', sans-serif; font-weight: 700; font-size: 0.95rem;
      color: var(--green-900); margin-bottom: 6px;
    }
    .seasonal-card__desc {
      font-size: 0.85rem; color: var(--text-light); margin-bottom: 12px; line-height: 1.5;
    }
    .seasonal-card__price {
      font-family: 'Poppins', sans-serif; font-weight: 800; font-size: 1.1rem;
      color: var(--orange-dark);
    }
    .seasonal-card:nth-child(1) .seasonal-card__image { background: linear-gradient(135deg, #E0F7FA, #B2EBF2); color: #00897B; }
    .seasonal-card:nth-child(2) .seasonal-card__image { background: linear-gradient(135deg, #FFF3E0, #FFE0B2); color: #E65100; }
    .seasonal-card:nth-child(3) .seasonal-card__image { background: linear-gradient(135deg, #EFEBE9, #D7CCC8); color: #5D4037; }
    .seasonal-card:nth-child(4) .seasonal-card__image { background: linear-gradient(135deg, #FFF9C4, #FFF59D); color: #F57F17; }

    /* ===== CATEGORIES ===== */
    .categories { padding: 80px 0; background: var(--white); }
    .categories__grid {
      display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
      gap: 24px;
    }
    .category-card {
      position: relative; border-radius: var(--radius); overflow: hidden;
      aspect-ratio: 1; cursor: pointer;
    }
    .category-card__bg {
      width: 100%; height: 100%; display: flex; align-items: center; justify-content: center;
      transition: transform var(--transition);
    }
    .category-card__bg svg { width: 56px; height: 56px; opacity: 0.4; }
    .category-card:nth-child(1) .category-card__bg { background: linear-gradient(135deg, #D8F3DC, #B7E4C7); color: var(--green-700); }
    .category-card:nth-child(2) .category-card__bg { background: linear-gradient(135deg, #FEF3C7, #FDE68A); color: #92400E; }
    .category-card:nth-child(3) .category-card__bg { background: linear-gradient(135deg, #DBEAFE, #BFDBFE); color: #1E40AF; }
    .category-card:nth-child(4) .category-card__bg { background: linear-gradient(135deg, #FFE4E6, #FECDD3); color: #BE123C; }
    .category-card:nth-child(5) .category-card__bg { background: linear-gradient(135deg, #FEF0E0, #FED7AA); color: #C2410C; }
    .category-card__overlay {
      position: absolute; inset: 0; background: rgba(27, 67, 50, 0.75);
      display: flex; flex-direction: column; align-items: center; justify-content: center;
      opacity: 0; transition: opacity var(--transition);
      padding: 20px; text-align: center;
    }
    .category-card:hover .category-card__bg { transform: scale(1.08); }
    .category-card:hover .category-card__overlay { opacity: 1; }
    .category-card:focus-visible .category-card__overlay { opacity: 1; }
    .category-card:focus-visible { outline: 3px solid var(--green-500); outline-offset: 2px; }
    .category-card__name {
      font-family: 'Poppins', sans-serif; font-weight: 700; font-size: 1.1rem;
      color: var(--white); margin-bottom: 8px;
    }
    .category-card__tagline {
      font-size: 0.85rem; color: rgba(255,255,255,0.85); line-height: 1.5;
    }

<!-- PLACEHOLDER_SECTION_3 -->
  </style>

