  .highlight-item__label {
    font-size: 0.95rem; color: rgba(255,255,255,0.8); font-weight: 600;
  }
  .highlight-item__desc {
    font-size: 0.8rem; color: rgba(255,255,255,0.6); margin-top: 4px;
  }

  /* ===== STORE LOCATOR ===== */
  .store-locator { padding: 80px 0; background: var(--cream); }
  .store-locator__form {
    display: flex; gap: 12px; max-width: 480px; margin: 0 auto 40px;
  }
  .store-locator__input {
    flex: 1; padding: 16px 24px; border: 2px solid var(--green-100);
    border-radius: 50px; font-size: 1rem; font-family: inherit;
    background: var(--white); color: var(--text-dark);
    transition: border-color var(--transition);
  }
  .store-locator__input:focus {
    outline: none; border-color: var(--green-500);
    box-shadow: 0 0 0 4px rgba(82, 183, 136, 0.15);
  }
  .store-locator__input::placeholder { color: var(--text-light); }
  .store-locator__btn {
    background: var(--green-700); color: var(--white); padding: 16px 32px;
    border-radius: 50px; font-weight: 700; font-size: 1rem;
    transition: all var(--transition); white-space: nowrap;
  }
  .store-locator__btn:hover { background: var(--green-600); }
  .store-locator__btn:focus-visible { outline: 3px solid var(--green-500); outline-offset: 2px; }
  .store-results { display: none; max-width: 700px; margin: 0 auto; }
  .store-results.active { display: block; }
  .store-card {
    background: var(--white); border-radius: var(--radius); padding: 24px;
    margin-bottom: 16px; box-shadow: var(--card-shadow);
    display: grid; grid-template-columns: 1fr auto; gap: 16px; align-items: center;
    transition: all var(--transition);
  }
  .store-card:hover { box-shadow: var(--card-shadow-hover); }
  .store-card__name {
    font-family: 'Poppins', sans-serif; font-weight: 700; font-size: 1.05rem;
    color: var(--green-900); margin-bottom: 4px;
  }
  .store-card__address { font-size: 0.9rem; color: var(--text-mid); margin-bottom: 4px; }
  .store-card__hours { font-size: 0.85rem; color: var(--text-light); }
  .store-card__distance {
    font-family: 'Poppins', sans-serif; font-weight: 800; font-size: 1.1rem;
    color: var(--orange); white-space: nowrap;
  }

  /* ===== NEWSLETTER ===== */
  .newsletter {
    padding: 80px 0;
    background: linear-gradient(135deg, var(--green-50) 0%, var(--cream) 100%);
  }
  .newsletter__form {
    display: flex; gap: 12px; max-width: 480px; margin: 0 auto;
  }
  .newsletter__input {
    flex: 1; padding: 16px 24px; border: 2px solid var(--green-100);
    border-radius: 50px; font-size: 1rem; font-family: inherit;
    background: var(--white); color: var(--text-dark);
    transition: border-color var(--transition);
  }
  .newsletter__input:focus {
    outline: none; border-color: var(--green-500);
    box-shadow: 0 0 0 4px rgba(82, 183, 136, 0.15);
  }
  .newsletter__input::placeholder { color: var(--text-light); }
  .newsletter__btn {
    background: var(--orange); color: var(--white); padding: 16px 32px;
    border-radius: 50px; font-weight: 700; font-size: 1rem;
    transition: all var(--transition); white-space: nowrap;
  }
  .newsletter__btn:hover { background: var(--orange-dark); }
  .newsletter__btn:focus-visible { outline: 3px solid var(--orange); outline-offset: 2px; }
  .newsletter__success {
    display: none; text-align: center; padding: 20px;
    background: var(--green-100); border-radius: var(--radius);
    color: var(--green-700); font-weight: 600; max-width: 480px; margin: 16px auto 0;
  }
  .newsletter__success.active { display: block; }

  /* ===== FOOTER ===== */
  .footer {
    padding: 60px 0 32px; background: var(--green-900); color: rgba(255,255,255,0.7);
  }
  .footer__grid {
    display: grid; grid-template-columns: repeat(4, 1fr); gap: 40px;
    max-width: var(--max-width); margin: 0 auto; padding: 0 24px 40px;
    border-bottom: 1px solid rgba(255,255,255,0.1);
  }
  .footer__col-title {
    font-family: 'Poppins', sans-serif; font-weight: 700; font-size: 0.95rem;
    color: var(--white); margin-bottom: 16px;
  }
  .footer__col a {
    display: block; padding: 4px 0; font-size: 0.9rem;
    transition: color var(--transition);
  }
  .footer__col a:hover { color: var(--green-500); }
  .footer__bottom {
    max-width: var(--max-width); margin: 0 auto; padding: 24px 24px 0;
    text-align: center; font-size: 0.85rem;
  }

  /* ===== RESPONSIVE ===== */
  @media (max-width: 1024px) {
    .hero__inner { grid-template-columns: 1fr; text-align: center; }
    .hero__subtitle { margin-left: auto; margin-right: auto; }
    .hero__actions { justify-content: center; }
    .hero__visual { display: none; }
    .highlights__grid { grid-template-columns: repeat(2, 1fr); }
    .footer__grid { grid-template-columns: repeat(2, 1fr); }
  }
  @media (max-width: 768px) {
    .header__nav { display: none; }
    .header__cta { display: none; }
    .header__mobile-toggle { display: block; }
    .hero { padding: 48px 0 40px; }
    .hero h1 { font-size: 2rem; }
    .hero__actions { flex-direction: column; align-items: center; }
    .btn-primary, .btn-secondary { width: 100%; justify-content: center; max-width: 320px; }
    .carousel__btn--prev { left: -8px; }
    .carousel__btn--next { right: -8px; }
    .carousel__btn { width: 40px; height: 40px; }
    .product-card { min-width: 220px; flex: 0 0 220px; }
    .categories__grid { grid-template-columns: repeat(2, 1fr); }
    .store-locator__form, .newsletter__form { flex-direction: column; }
    .store-card { grid-template-columns: 1fr; }
    .store-card__distance { text-align: left; }
    .footer__grid { grid-template-columns: 1fr; gap: 24px; }
  }
  @media (max-width: 480px) {
    .highlights__grid { grid-template-columns: repeat(2, 1fr); gap: 20px; }
    .categories__grid { grid-template-columns: 1fr 1fr; gap: 16px; }
    .seasonal__grid { grid-template-columns: 1fr; }
  }

  @media (prefers-reduced-motion: reduce) {
    *, *::before, *::after { animation-duration: 0.01ms !important; transition-duration: 0.01ms !important; }
    .carousel__track { transition: none; }
  }
</style>

