arguments.command:
python3 -c "
from html.parser import HTMLParser

class Validator(HTMLParser):
    def __init__(self):
        super().__init__()
        self.errors = []
        self.stack = []
        self.void = {'area','base','br','col','embed','hr','img','input','link','meta','source','track','wbr'}
    def handle_starttag(self, tag, attrs):
        if tag not in self.void:
            self.stack.append(tag)
    def handle_endtag(self, tag):
        if tag in self.void:
            return
        if self.stack and self.stack[-1] == tag:
            self.stack.pop()
        else:
            self.errors.append(f'Mismatched: </{tag}> (expected </{self.stack[-1] if self.stack else \"?\"}>)')

v = Validator()
v.feed(open('/app/output/index.html').read())
if v.errors:
    for e in v.errors[:10]:
        print('ERROR:', e)
else:
    print('HTML structure: valid (no mismatched tags)')
print(f'Unclosed tags: {len(v.stack)}', v.stack[:5] if v.stack else '')
"

